    public long InserttoVehicleListTable(ArrayList<VehicleList> menuVehicleList) {
        TruncateTableByTableName("DO_tracking");
        long status = 0;
        int ii;
        database.beginTransaction();
        try {
            for (ii = 0; ii < menuVehicleList.size(); ii++) {
                VehicleList obj = menuVehicleList.get(ii);
                ContentValues cv = new ContentValues();
                cv.put("customer_code", obj.get_customer_code());
                cv.put("destination", obj.get_destination());
                cv.put("DO_no", obj.get_DO_no());
                cv.put("vehicle_no", obj.get_vehicle_no());
                cv.put("trans_response_id", obj.get_trans_response_id());
                cv.put("transporter", obj.get_transporter());
                cv.put("arrival_gate_id", obj.get_arrival_gate_id());
                cv.put("gate_keeper1", obj.get_gate_keeper1());
                cv.put("despatch_approval_id", obj.get_despatch_approval_id());
                cv.put("despatch_in", obj.get_despatch_in());
                cv.put("gate_vehicle_in_id", obj.get_gate_vehicle_in_id());
                cv.put("gate_keeper2", obj.get_gate_keeper2());
                cv.put("wb_in_id", obj.get_wb_in_id());
                cv.put("weighbridge_in", obj.get_weighbridge_in());
                cv.put("tare_weight", obj.get_tare_weight());
                cv.put("loading_id", obj.get_loading_id());
                cv.put("loading", obj.get_loading());
                cv.put("GRN_attachment", obj.get_GRN_attachment());
                cv.put("GRN_attachment_date", obj.get_GRN_attachment_date());
                cv.put("bay_no", obj.get_bay_no());
                cv.put("wb_out_id", obj.get_wb_out_id());
                cv.put("weighbridge_out", obj.get_weighbridge_out());
                cv.put("despatch_tarns_id", obj.get_despatch_tarns_id());
                cv.put("despatch_out", obj.get_despatch_out());
                cv.put("exit_approval_id", obj.get_exit_approval_id());
                cv.put("gate_keeper2_out", obj.get_gate_keeper2_out());
                cv.put("security_chk_id", obj.get_security_chk_id());
                cv.put("security_out", obj.get_security_out());
                cv.put("exit_gate_id", obj.get_exit_gate_id());
                cv.put("gate_keeper1_out", obj.get_gate_keeper1_out());
                synchronized (Lock) {
                    database.insertWithOnConflict("DO_tracking", null, cv, SQLiteDatabase.CONFLICT_IGNORE);
                }
            }
            status = ii;
            database.setTransactionSuccessful();
        } catch (SQLException ignored) {
        } finally {
            database.endTransaction();
        }
        return status;
    }

    public long insertTo_DO_despatch_details(ArrayList<DO_despatch_details> grpList) {
        TruncateTableByTableName("DO_despatch_details");
        long status = 0;
        int ii;
        database.beginTransaction();
        try {
            for (ii = 0; ii < grpList.size(); ii++) {
                DO_despatch_details obj = grpList.get(ii);
                ContentValues cv = new ContentValues();
                cv.put("sauda_no", obj.get_sauda_no());
                cv.put("customer_code", obj.get_customer_code());
                cv.put("destination", obj.get_destination());
                cv.put("DO_no", obj.get_DO_no());
                cv.put("sku_code", obj.get_sku_code());
                cv.put("batch_no", obj.get_batch_no());
                cv.put("DO_qty", obj.get_DO_qty());
                cv.put("DO_rate", obj.get_DO_rate());
                cv.put("DO_amount", obj.get_DO_amount());
                cv.put("DO_date", obj.get_DO_date());
                cv.put("loading_qty", obj.get_loading_qty());
                cv.put("invoice_no", obj.get_invoice_no());
                cv.put("invoice_amount", obj.get_invoice_amount());
                cv.put("invoice_date", obj.get_invoice_date());
                synchronized (Lock) {
                    database.insertWithOnConflict("DO_despatch_details", null, cv, SQLiteDatabase.CONFLICT_IGNORE);
                }
            }
            status = ii;
            database.setTransactionSuccessful();
        } catch (SQLException ignored) {
        } finally {
            database.endTransaction();
        }
        return status;
    }

