    @SuppressLint("Recycle")
    public Double GetOpeningStockLedger(String daterange, String DateRangePayment) {
        double GetOpeningStockLedger = 0.0;
        String query;
        Cursor cursor = null;
        try {
            query = "select sum(substr(d_instruction,instr(d_instruction,';')+12)) from order_header where customer_code='" + Constants.selectedCustomer.getCustomerCode() + "' AND " + daterange;
            cursor = database.rawQuery(query, null);
            if (cursor.getCount() > 0) {
                cursor.moveToFirst();
                GetOpeningStockLedger = cursor.getDouble(0);
            }
            query = "select Sum(amount) from payment_header where customer_code='" + Constants.selectedCustomer.getCustomerCode() + "' AND " + DateRangePayment;
            cursor = null;
            cursor = database.rawQuery(query, null);
            if (cursor.getCount() > 0) {
                cursor.moveToFirst();
                GetOpeningStockLedger = GetOpeningStockLedger - cursor.getDouble(0);
                cursor.close();
            }
        } catch (Exception ignored) {
        } finally {
            if (cursor != null) {
                cursor.close();
            }
        }
        return GetOpeningStockLedger;
    }

