    @SuppressLint("Recycle")
    public EmployeeTargetJCP GetEmployeeTargetJCPOld(String condition, String type) {
        EmployeeTargetJCP obj = new EmployeeTargetJCP();
        String query;
        int total = 0;
        int other = 0;
        int ihb = 0;
        Cursor cursor = null;
        try {
            if (type.equalsIgnoreCase("TARGET")) {
                query = "SELECT CM.cust_type,COUNT(RCPT.customer_code)  FROM customer_master CM,route_customer_plan_transaction RCPT WHERE CM.customer_code=RCPT.customer_code AND RCPT.visit_date='" + condition + "'  GROUP BY CM.cust_type";
            } else {
                query = "SELECT CM.cust_type,COUNT(OH.customer_code)  FROM customer_master CM,order_header OH WHERE CM.customer_code=OH.customer_code AND SUBSTR(OH.order_no,-14,8)='" + condition + "'  GROUP BY CM.cust_type";
            }
            if (type.equalsIgnoreCase("ACHIEVED")) {
                Cursor cursor1;
                String query1 = "SELECT type,COUNT(DISTINCT survey_id)  FROM survey_output WHERE  SUBSTR(survey_id,-14,8)='" + condition + "' GROUP BY survey_id";
                cursor1 = database.rawQuery(query1, null);
                if (cursor1.getCount() > 0) {
                    cursor1.moveToFirst();
                    for (int ii = 0; ii < cursor1.getCount(); ii++) {
                        if (cursor1.getString(0).trim().equalsIgnoreCase("New IHB")) {
                            if (cursor1.getString(1) != null && !cursor1.getString(1).trim().isEmpty()) {
                                ihb += Integer.parseInt(cursor1.getString(1));
                                total += Integer.parseInt(cursor1.getString(1));
                            }
                        } else if (cursor1.getString(0).trim().equalsIgnoreCase("Existing IHB")) {
                            if (cursor1.getString(1) != null && !cursor1.getString(1).trim().isEmpty()) {
                                ihb += Integer.parseInt(cursor1.getString(1));
                                total += Integer.parseInt(cursor1.getString(1));
                            }
                        } else {
                            if (cursor1.getString(1) != null && !cursor1.getString(1).trim().isEmpty()) {
                                other += Integer.parseInt(cursor1.getString(1));
                                total += Integer.parseInt(cursor1.getString(1));
                            }
                        }
                        cursor1.moveToNext();
                    }
                    obj.setIHB(String.valueOf(ihb));
                }
            }
            cursor = database.rawQuery(query, null);
            if (cursor.getCount() > 0) {
                cursor.moveToFirst();
                for (int ii = 0; ii < cursor.getCount(); ii++) {
                    if (cursor.getString(0).trim().equalsIgnoreCase("Dealer") || cursor.getString(0).trim().equalsIgnoreCase("D")) {
                        if (cursor.getString(1) != null && !cursor.getString(1).trim().isEmpty()) {
                            obj.setDealer(cursor.getString(1));
                            total += Integer.parseInt(cursor.getString(1));
                        }
                    } else if (cursor.getString(0).trim().equalsIgnoreCase("Sub-Dealer") || cursor.getString(0).trim().equalsIgnoreCase("SD")) {
                        if (cursor.getString(1) != null && !cursor.getString(1).trim().isEmpty()) {
                            obj.setSubDealer(cursor.getString(1));
                            total += Integer.parseInt(cursor.getString(1));
                        }
                    } else if (cursor.getString(0).trim().equalsIgnoreCase("Retailer") || cursor.getString(0).trim().equalsIgnoreCase("R")) {
                        if (cursor.getString(1) != null && !cursor.getString(1).trim().isEmpty()) {
                            obj.setRetailer(cursor.getString(1));
                            total += Integer.parseInt(cursor.getString(1));
                        }
                    } else if (cursor.getString(0).trim().equalsIgnoreCase("SS") || cursor.getString(0).trim().equalsIgnoreCase("super stockist")) {
                        if (cursor.getString(1) != null && !cursor.getString(1).trim().isEmpty()) {
                            obj.setSS(cursor.getString(1));
                            total += Integer.parseInt(cursor.getString(1));
                        }
                    } else {
                        if (cursor.getString(1) != null && !cursor.getString(1).trim().isEmpty()) {
                            other += Integer.parseInt(cursor.getString(1));
                            total += Integer.parseInt(cursor.getString(1));
                        }
                    }
                    cursor.moveToNext();
                }
                cursor.close();
                obj.setOthers(String.valueOf(other));
                obj.setAchievement(String.valueOf(total));
            }
        } catch (Exception ignored) {
        } finally {
            if (cursor != null) {
                cursor.close();
            }
        }
        return obj;
    }

    public EmployeeTargetJCP GetEmployeeTargetJCP(String empCodeCondition) {
        EmployeeTargetJCP obj = new EmployeeTargetJCP();
        Cursor cursor;
        obj.setIHB("");
        obj.setOthers("");
        try {
            String queryToGetAchievement = "select count(customer_code) from emp_target_achievement where lower(cust_type)='ss'" + empCodeCondition;
            cursor = database.rawQuery(queryToGetAchievement, null);
            cursor.moveToFirst();
            obj.setSS(cursor.getString(0));
            cursor.close();

            queryToGetAchievement = "select count(customer_code) from emp_target_achievement where lower(cust_type)='d'" + empCodeCondition;
            cursor = database.rawQuery(queryToGetAchievement, null);
            cursor.moveToFirst();
            obj.setDealer(cursor.getString(0));
            cursor.close();

            queryToGetAchievement = "select count(customer_code) from emp_target_achievement where lower(cust_type)='sd'" + empCodeCondition;
            cursor = database.rawQuery(queryToGetAchievement, null);
            cursor.moveToFirst();
            obj.setSubDealer(cursor.getString(0));
            cursor.close();

            queryToGetAchievement = "select count(customer_code) from emp_target_achievement where lower(cust_type)='sd'" + empCodeCondition;
            cursor = database.rawQuery(queryToGetAchievement, null);
            cursor.moveToFirst();
            obj.setRetailer(cursor.getString(0));
            cursor.close();

            int totalAchievement = Integer.parseInt(obj.getSS()) + Integer.parseInt(obj.getDealer()) + Integer.parseInt(obj.getSubDealer()) + Integer.parseInt(obj.getRetailer());
            obj.setAchievement(String.valueOf(totalAchievement));
        } catch (Exception ignored) {
            obj.setSS("0");
            obj.setDealer("0");
            obj.setSubDealer("0");
            obj.setRetailer("0");
        }
        return obj;
    }

    public double GetEmployeeTargetVolume(String condition, String empcode, String type) {
        double value = 0;
        String query;
        if (type.equalsIgnoreCase("SINGLE")) {
            query = "SELECT SUM(volume_target),SUM(volume_achievement) FROM emp_target_achievement WHERE " + condition + " AND emp_code='" + empcode + "'";
        } else {
            query = "SELECT SUM(volume_target),SUM(volume_achievement) FROM emp_target_achievement WHERE " + condition + " AND emp_code IN(" + empcode + ")";
        }
        try (Cursor cursor = database.rawQuery(query, null)) {
            if (cursor.getCount() > 0) {
                cursor.moveToFirst();
                double volumeacheived = 0;
                double volumetarget = 0;
                if (!cursor.getString(0).trim().isEmpty()) {
                    volumetarget = Double.parseDouble(cursor.getString(0).trim());
                }
                if (!cursor.getString(1).trim().isEmpty()) {
                    volumeacheived = Double.parseDouble(cursor.getString(1).trim());
                }
                value = (volumeacheived / volumetarget) * 100;
            }
        } catch (Exception ignored) {
        }
        return value;
    }

