    public void insertOrUpdateAppInfo(String nickName, String appVersion, String dbVersion, byte[] logo, String condition) {
        Cursor cursors;
        cursors = database.rawQuery("SELECT app_version FROM app_info", null);
        if (cursors.getCount() > 0) {
            database.beginTransaction();
            try {
                ContentValues cv = new ContentValues();
                cv.put("db_version", dbVersion);
                if (condition.equalsIgnoreCase("Y")) {
                    cv.put("base_url", BaseUrl.baseUrl);
                }
                synchronized (Lock) {
                    database.update("app_info", cv, null, null);
                }
                database.setTransactionSuccessful();
            } catch (SQLException ignored) {
            } finally {
                database.endTransaction();
                cursors.close();
            }
        } else {
            database.beginTransaction();
            try {
                ContentValues cv = new ContentValues();
                cv.put("nick_name", nickName);
                cv.put("app_version", appVersion);
                cv.put("db_version", dbVersion);
                cv.put("logo", logo);
                cv.put("base_url", BaseUrl.baseUrl);
                synchronized (Lock) {
                    database.insertWithOnConflict("app_info", null, cv, SQLiteDatabase.CONFLICT_IGNORE);
                }
                database.setTransactionSuccessful();
            } catch (SQLException ignored) {
            } finally {
                database.endTransaction();
            }
        }
    }

    public void updateAppVersion(Context context) {
        database.beginTransaction();
        try {
            ContentValues cv = new ContentValues();
            cv.put("app_version", Utils.getAppVersion(context));
            synchronized (Lock) {
                database.update("app_info", cv, null, null);
            }
            database.setTransactionSuccessful();
        } catch (SQLException ignored) {
        } finally {
            database.endTransaction();
        }
    }

