    public void saveUserImage(byte[] imgArray) {
        database.beginTransaction();
        database.execSQL("DELETE FROM emp_image");
        try {
            ContentValues cv = new ContentValues();
            cv.put("profile_image", imgArray);
            synchronized (Lock) {
                database.insertWithOnConflict("emp_image", null, cv, SQLiteDatabase.CONFLICT_IGNORE);
            }
            database.setTransactionSuccessful();
        } catch (SQLException ignored) {
        } finally {
            database.endTransaction();
        }
    }

