    public void getProductListForRaNewBid(String plantName, String productGroup) {
        String selectQuery;
        if (productGroup.matches("")) {
            selectQuery = "SELECT distinct ra.prod_code,ra.plant_name,ra.release_rate,pm.prod_desc,pm.dns_prod_code,ra.base_rate,ra.indicative_rate,ra.GST_percent,pm.conversion_factor,pm.conversion_factor_two FROM plant_product_wise_RA_rate ra, product_master pm where ra.prod_code=pm.dns_prod_code and ra.prod_code not in (select distinct prod_code from RA_bid_rate_details where substr(bid_id,-14,8)='" + dateString + "' AND substr(bid_id,-6,6) >= '" + currentWindowStartsAt + "' AND substr(bid_id,-6,6) <= '" + currentWindowClosesAt + "'  AND customer_code='" + Constants.selectedCustomer.getCustomerCode() + "') and LOWER(ra.plant_name)='" + plantName.toLowerCase() + "'and  LOWER(ra.acedns)='y' and LOWER(pm.acedns)='y'";
        } else {
            selectQuery = "SELECT distinct ra.prod_code,ra.plant_name,ra.release_rate,pm.prod_desc,pm.dns_prod_code,ra.base_rate,ra.indicative_rate,ra.GST_percent,pm.conversion_factor,pm.conversion_factor_two FROM plant_product_wise_RA_rate ra, product_master pm where ra.prod_code=pm.dns_prod_code and pm.product_group_code='" + productGroup + "' and ra.prod_code not in (select distinct prod_code from RA_bid_rate_details where substr(bid_id,-14,8)='" + dateString + "' AND substr(bid_id,-6,6) >= '" + currentWindowStartsAt + "' AND substr(bid_id,-6,6) <= '" + currentWindowClosesAt + "' AND customer_code='" + Constants.selectedCustomer.getCustomerCode() + "') and LOWER(ra.plant_name)='" + plantName.toLowerCase() + "'and  LOWER(ra.acedns)='y' and LOWER(pm.acedns)='y'";
        }
        plantListForRANewBid = new ArrayList<>();
        plantListForRANewBidCopy = new ArrayList<>();
        try (Cursor cursor = database.rawQuery(selectQuery, null)) {
            if (cursor.getCount() > 0) {
                cursor.moveToFirst();
                for (int i = 0; i < cursor.getCount(); i++) {
                    PlantProductWiseRARate item = new PlantProductWiseRARate();
                    item.setPlantName(cursor.getString(1));
                    item.setProdCode(cursor.getString(0));
                    double rate = Double.parseDouble(cursor.getString(2));
                    item.setReleaseRate(defaultFormat.format(rate));
                    String serverIndicativeRate = cursor.getString(6);
                    item.setIndicativeRateApp(defaultFormat.format(Double.valueOf(serverIndicativeRate)));
                    item.setprodName(cursor.getString(3));
                    String dnsProdCode = cursor.getString(4);
                    item.setDnsProdCode(dnsProdCode);
                    item.setBaseRate(cursor.getString(5));
                    item.setIndicativeRateServer(defaultFormat.format(Double.valueOf(serverIndicativeRate)));
                    item.setgstPercent(cursor.getString(7));
                    item.setconversionFactorOne(cursor.getString(8));
                    item.setconversionFactorTwo(cursor.getString(9));
                    String marginCost = GetRAMarginCostByProductCode(dnsProdCode);
                    item.setmarginCost(marginCost);
                    if (Utils.isNumeric(marginCost)) {
                        plantListForRANewBidCopy.add(item);
                    }
                    cursor.moveToNext();
                }
            }
        } catch (Exception ignored) {
        }
    }

