    public ArrayList<RADateWiseWindowTime> getWindowOpenCloseTimingForToday() {
        String selectQuery;
        Cursor cursor = null;
        ArrayList<RADateWiseWindowTime> WindowOpenCloseTimingForToday = new ArrayList<>();
        try {
            selectQuery = "SELECT time_from,time_to from RA_windowtime";
            cursor = database.rawQuery(selectQuery, null);
            if (cursor.getCount() > 0) {
                cursor.moveToFirst();
                for (int i = 0; i < cursor.getCount(); i++) {
                    RADateWiseWindowTime item = new RADateWiseWindowTime();
                    item.setTimeFrom(cursor.getString(0));
                    item.setTimeTo(cursor.getString(1));
                    WindowOpenCloseTimingForToday.add(item);
                    cursor.moveToNext();
                }
            }
            cursor.close();
        } catch (Exception ignored) {
        } finally {
            if (cursor != null) {
                cursor.close();
            }
        }
        return WindowOpenCloseTimingForToday;
    }

