    public boolean deleteCustomerAndRelatedData(String customerToDeleteList) {
        boolean isdeletionOK;
        database.beginTransaction();
        try {
            database.execSQL("delete from location where trans_id IN(select transaction_id from stock_audit where customer_code IN(" + customerToDeleteList + ") Union select order_no from order_header where customer_code IN(" + customerToDeleteList + "))");
            database.execSQL("delete from stock_audit where customer_code IN(" + customerToDeleteList + ")");
            database.execSQL("delete from order_details where order_no IN(select order_no from order_header where customer_code IN(" + customerToDeleteList + "))");
            database.execSQL("delete from order_header where customer_code IN(" + customerToDeleteList + ")");
            database.execSQL("delete from customer_master where customer_code IN(" + customerToDeleteList + ")");
            database.setTransactionSuccessful();
            isdeletionOK = true;
        } catch (SQLException ignored) {
            isdeletionOK = false;
        } finally {
            database.endTransaction();
        }
        return isdeletionOK;
    }

