    public String GetCompetitorName() {
        StringBuilder name = new StringBuilder();
        Cursor cursor = null, cursor1;
        Constants.productType = new ArrayList<>();
        try {
            Constants.competitorPoductType = new ArrayList<>();
            if (Constants.nickName.equalsIgnoreCase("STAR")) {
                String query = "SELECT branch_code FROM customer_master WHERE customer_code='" + Constants.selectedCustomer.getCustomerCode() + "'";
                cursor = database.rawQuery(query, null);
                String[] typeProduct = {"MANDATORY STAR", "BENCHMARK COMPETITOR", "OPTIONAL STAR", "OTHER COMPETITOR"};
                if (cursor.getCount() > 0) {
                    cursor.moveToFirst();
                    String b_code = cursor.getString(0);
                    MarketFeedbackStockAudit mf;
                    for (String s : typeProduct) {
                        String query1 = "SELECT DISTINCT(competitor_name), product_type FROM competitor_group_master WHERE product_type='" + s + "' AND branch_code='" + b_code + "'  ORDER BY group_name ASC";
                        cursor1 = database.rawQuery(query1, null);
                        if (cursor1.getCount() > 0) {
                            cursor1.moveToFirst();
                            for (int ii1 = 0; ii1 < cursor1.getCount(); ii1++) {
                                name.append(cursor1.getString(0));
                                name.append(",");
                                Constants.productType.add(cursor1.getString(1));
                                mf = new MarketFeedbackStockAudit();
                                mf.setCompetitorName(cursor1.getString(0));
                                mf.setProductType(cursor1.getString(1));
                                Constants.competitorPoductType.add(mf);
                                cursor1.moveToNext();
                            }
                            cursor1.close();
                        }
                    }
                    cursor.close();
                }
            } else {
                String query = "SELECT DISTINCT(competitor_name), product_type FROM competitor_group_master  ORDER BY group_name ASC";
                cursor = database.rawQuery(query, null);
                if (cursor.getCount() > 0) {
                    cursor.moveToFirst();
                    MarketFeedbackStockAudit mf;
                    for (int ii = 0; ii < cursor.getCount(); ii++) {
                        name.append(cursor.getString(0));
                        if (ii < cursor.getCount()) {
                            name.append(",");
                        }
                        Constants.productType.add(cursor.getString(1));
                        mf = new MarketFeedbackStockAudit();
                        mf.setCompetitorName(cursor.getString(0));
                        mf.setProductType(cursor.getString(1));
                        Constants.competitorPoductType.add(mf);
                        cursor.moveToNext();
                    }
                    cursor.close();
                }
            }
        } catch (Exception ignored) {
        } finally {
            if (cursor != null) {
                cursor.close();
            }
        }
        return name.toString();
    }

