    @SuppressLint("SimpleDateFormat")
    public void DeleteNotificationDataFromLocationAndNotificationTable() {
        database.beginTransaction();
        try {
            String listOfNotificationsNotFromToday = "";
            String selectQuery = "SELECT notification_id from notification_details where substr(notification_id,-14,8)!='" + new SimpleDateFormat("yyyyMMdd").format(new Date()) + "' ";
            Cursor cursor = database.rawQuery(selectQuery, null);
            if (cursor.moveToFirst()) {
                StringBuilder listOfNotificationsNotFromTodayBuilder = new StringBuilder();
                do {
                    if (listOfNotificationsNotFromTodayBuilder.toString().matches("")) {
                        listOfNotificationsNotFromTodayBuilder = new StringBuilder("'" + cursor.getString(0) + "'");
                    } else {
                        listOfNotificationsNotFromTodayBuilder.append(",'").append(cursor.getString(0)).append("'");
                    }
                }
                while (cursor.moveToNext());
                listOfNotificationsNotFromToday = listOfNotificationsNotFromTodayBuilder.toString();
            }
            cursor.close();
            StringBuilder listOfAcknowledgementsNotFromToday = new StringBuilder();
            selectQuery = "SELECT ack_id from notification_details where ack_id!='' and notification_id in (" + listOfNotificationsNotFromToday + ")";
            cursor = database.rawQuery(selectQuery, null);
            if (cursor.moveToFirst()) {
                do {
                    if (listOfAcknowledgementsNotFromToday.toString().matches("")) {
                        listOfAcknowledgementsNotFromToday = new StringBuilder("'" + cursor.getString(0) + "'");
                    } else {
                        listOfAcknowledgementsNotFromToday.append(",'").append(cursor.getString(0)).append("'");
                    }
                }
                while (cursor.moveToNext());
            }
            cursor.close();
            database.execSQL("delete from notification_details where notification_id in (" + listOfNotificationsNotFromToday + ")");
            database.execSQL("delete from location where trans_id in(" + listOfAcknowledgementsNotFromToday + ")");
            database.setTransactionSuccessful();
        } catch (Exception ignored) {
        } finally {
            database.endTransaction();
        }
    }

    public void TruncateTableByTableName(String tableName) {
        database.beginTransaction();
        try {
            database.execSQL("DELETE FROM " + tableName);
            database.setTransactionSuccessful();
        } catch (Exception ignored) {
        } finally {
            database.endTransaction();
        }
    }

