    public String FormatDate(String orderno) {
        String subdate;
        String finaldate = "";
        if (!orderno.isEmpty()) {
            subdate = orderno.substring(6, 14);
            finaldate = subdate.substring(6, 8) + "-" + subdate.substring(4, 6) + "-" + subdate.substring(0, 4);
        }
        return finaldate;
    }

