    public void GetReverseAuctionCustomers() {
        customerDetailsListReverseAuction = new ArrayList<>();
        try (Cursor cursor = database.rawQuery("SELECT * FROM customer_master WHERE lower(sauda_type)='ra' AND lower(acedns)='y'", null)) {
            if (cursor.getCount() > 0) {
                cursor.moveToFirst();
                for (int ii = 0; ii < cursor.getCount(); ii++) {
                    CustomerDetails detailsObj = getCustomerDetailsItemWise(cursor);
                    double saudaLimit = 0.0, pendingQty = 0.0;
                    if (Utils.isNumeric(detailsObj.getSaudaLimit())) {
                        saudaLimit = Double.parseDouble(detailsObj.getSaudaLimit());
                    }
                    if (Utils.isNumeric(detailsObj.getPendingQty())) {
                        pendingQty = Double.parseDouble(detailsObj.getPendingQty());
                    }
                    if (saudaLimit - pendingQty > 0) {
                        customerDetailsListReverseAuction.add(detailsObj);
                    }
                    cursor.moveToNext();
                }
            }
        } catch (Exception ignored) {
        }
    }

