    public ArrayList<RoutePlanMasterDetails> getRouteByCode(String c) {
        int allCustomeCount = 0;
        ArrayList<RoutePlanMasterDetails> routePlanList = new ArrayList<>();
        selectedAllRouteForCurrentDistributor = new ArrayList<>();
        Cursor cursor = null;
        try {
            String selectQuery = "SELECT DISTINCT RM.route_code,RM.route_name FROM route_master RM,customer_master CM where CM.route_code=RM.route_code AND CM.acedns = 'Y' AND CM.black_list = 'N' \n" + "and CM.is_new_customer !='yes' AND CM.CI_logic='N' AND CM.cust_type='R' AND CM.rds_tag='" + c + "'" + " order by lower(RM.route_name)";
            cursor = database.rawQuery(selectQuery, null);
            if (cursor.getCount() > 0) {
                if (cursor.getCount() > 1) {
                    RoutePlanMasterDetails routeObjAll = new RoutePlanMasterDetails();
                    routeObjAll.setRouteName("ALL");
                    routeObjAll.setRoutecode("all");
                    routeObjAll.setcustomerCount("0");
                    routePlanList.add(routeObjAll);
                }
                cursor.moveToFirst();
                for (int i = 0; i < cursor.getCount(); i++) {
                    RoutePlanMasterDetails routeObj = new RoutePlanMasterDetails();
                    routeObj.setRouteName(cursor.getString(1));
                    routeObj.setRoutecode(cursor.getString(0));
                    selectedAllRouteForCurrentDistributor.add(cursor.getString(0));
                    String sqlQueryToGetCustomerCountByRouteCode = "select distinct count(customer_code) from customer_master where route_code='" + cursor.getString(0) + "' AND acedns='Y' AND rds_tag='" + c + "' AND is_new_customer !='yes' AND CI_logic='N'";
                    Cursor Cursor2 = database.rawQuery(sqlQueryToGetCustomerCountByRouteCode, null);
                    String count = "0";
                    if (Cursor2.getCount() > 0) {
                        Cursor2.moveToFirst();
                        count = Cursor2.getString(0);
                        Cursor2.close();
                    }
                    allCustomeCount = allCustomeCount + Integer.parseInt(count);
                    routeObj.setcustomerCount(count);
                    routePlanList.add(routeObj);
                    cursor.moveToNext();
                }
            }
            cursor.close();
        } catch (Exception ignored) {
        } finally {
            if (cursor != null) {
                cursor.close();
            }
        }
        if (routePlanList.size() > 2) {
            routePlanList.get(0).setcustomerCount(String.valueOf(allCustomeCount));
        }
        return routePlanList;
    }

