    public TreeMap<String, ArrayList<commonDatabaseHelper>> getPendingOrderListByCustomerCode(String customerCode) {
        TreeMap<String, ArrayList<commonDatabaseHelper>> detailList = new TreeMap<>();
        try (Cursor cursor = database.rawQuery("SELECT id,APPORDERNO,order_date,order_for,customer_code,dns_customer_code,sub_dealer_code,prod_code ,dns_prod_code,prod_display_name" + ",QTY,STATUS,freight,destination_code,destination_name,destination_address,phone_no,dump_status,dump_code,dump_name,dealer_truck,order_by,consignee_address FROM T_APPERPDO_APPROVAL where lower(approval_status)='pending' AND customer_code='" + customerCode + "' order by id ", null)) {
            int count = cursor.getCount();
            if (count > 0) {
                cursor.moveToFirst();
                for (int ii = 0; ii < count; ii++) {
                    commonDatabaseHelper temp = new commonDatabaseHelper();
                    temp.setItem0(cursor.getString(0));
                    String orderNumber = cursor.getString(1);
                    temp.setItem1(orderNumber);
                    temp.setItem2(cursor.getString(2));
                    temp.setItem3(cursor.getString(3));
                    temp.setItem4(cursor.getString(4));
                    temp.setItem5(cursor.getString(5));
                    temp.setItem6(cursor.getString(6));
                    temp.setItem7(cursor.getString(7));
                    temp.setItem8(cursor.getString(8));
                    temp.setchangedDnsProdCode(cursor.getString(8));
                    temp.setItem9(cursor.getString(9));
                    temp.setItem10(cursor.getString(10));
                    temp.setchangedqty(cursor.getString(10));
                    temp.setItem11(cursor.getString(11));
                    temp.setItem12(cursor.getString(12));
                    temp.setItem13(cursor.getString(13));
                    temp.setItem14(cursor.getString(14));
                    temp.setItem15(cursor.getString(15));
                    temp.setItem16(cursor.getString(16));
                    temp.setItem17(cursor.getString(17));
                    temp.setItem18(cursor.getString(18));
                    temp.setItem19(cursor.getString(19));
                    temp.setItem20(cursor.getString(20));
                    temp.setItem21(cursor.getString(21));
                    temp.setItem22(cursor.getString(22));
                    temp.setplantName("");
                    temp.setchangedDumpCode(cursor.getString(18));
                    temp.setchangedDnsDestinationCode(cursor.getString(13));
                    temp.setchangedConsigneeAddress(cursor.getString(22));
                    if (!detailList.isEmpty()) {
                        boolean OrderExistsInList = false;
                        for (Map.Entry<String, ArrayList<commonDatabaseHelper>> stringArrayListEntry : detailList.entrySet()) {
                            String key = ((Map.Entry) stringArrayListEntry).getKey().toString();
                            if (key.equalsIgnoreCase(orderNumber)) {
                                detailList.get(orderNumber).add(temp);
                                OrderExistsInList = true;
                                break;
                            }
                        }
                        if (!OrderExistsInList) {
                            ArrayList<commonDatabaseHelper> listOfCurrentOrder = new ArrayList<>();
                            listOfCurrentOrder.add(temp);
                            detailList.put(orderNumber, listOfCurrentOrder);
                        }
                    } else {
                        ArrayList<commonDatabaseHelper> listOfCurrentOrder = new ArrayList<>();
                        listOfCurrentOrder.add(temp);
                        detailList.put(orderNumber, listOfCurrentOrder);
                    }
                    cursor.moveToNext();
                }
                return detailList;
            }
        } catch (Exception ignored) {
        }
        return detailList;
    }

