    @SuppressLint("Recycle")
    public ArrayList<BranchMasterDetails> GETDEPOList(String type) {
        ArrayList<BranchMasterDetails> detailList = new ArrayList<>();
        Cursor cursor = null;
        try {
            if (type.equalsIgnoreCase("sauda")) {
                String sql = "SELECT BM.company_code, MRP.branch_code,BM.branch_name,BM.Hq,BM.is_plant,BM.dns_state_code FROM branch_master BM, sauda_mrp MRP WHERE MRP.branch_code=BM.branch_code GROUP BY  MRP.branch_code";
                if (Constants.saudaFormDetailsObj.getincoterms_vertical().contains(getVerticalValueOfLoggedInEmployee())) {
                    String branchlist = "";
                    String sqlBranchListByEmpQuery = "SELECT branch_code from emp_master where emp_code='" + Constants.employeeDetailObject.getEmpCode() + "'";
                    Cursor cursor2 = database.rawQuery(sqlBranchListByEmpQuery, null);
                    if (cursor2.getCount() > 0) {
                        cursor2.moveToFirst();
                        branchlist = cursor2.getString(0);
                    }
                    sql = "SELECT BM.company_code, MRP.branch_code,BM.branch_name,BM.Hq,BM.is_plant,BM.dns_state_code FROM branch_master BM, sauda_mrp MRP WHERE MRP.branch_code=BM.branch_code AND BM.branch_code IN(" + Utils.convertCommaSeparatedListToProperFormat(branchlist) + ") GROUP BY  MRP.branch_code";
                }
                cursor = database.rawQuery(sql, null);
            } else {
                cursor = database.rawQuery("SELECT BM.company_code, MRP.branch_code,BM.branch_name,BM.Hq FROM branch_master BM, mrp MRP WHERE MRP.branch_code=BM.branch_code GROUP BY  MRP.branch_code", null);
            }
            if (cursor.getCount() > 0) {
                cursor.moveToFirst();
                for (int ii = 0; ii < cursor.getCount(); ii++) {
                    BranchMasterDetails detailsObj = new BranchMasterDetails();
                    detailsObj.setCompanyCode(cursor.getString(0));
                    detailsObj.setBranchCode(cursor.getString(1));
                    detailsObj.setBranchName(cursor.getString(2));
                    detailsObj.setHq(cursor.getString(3));
                    if (type.equalsIgnoreCase("sauda")) {
                        detailsObj.setisPlant(cursor.getString(4));
                        detailsObj.setbranch_state(cursor.getString(5));
                    }
                    detailList.add(detailsObj);
                    cursor.moveToNext();
                }
                cursor.close();
                return detailList;
            }
        } catch (Exception ignored) {
        } finally {
            if (cursor != null) {
                cursor.close();
            }
        }
        return detailList;
    }

