    public ArrayList<CustomerDetails> getCustomerListByRouteWithOS(String routeCode) {
        ArrayList<CustomerDetails> detailList = new ArrayList<>();
        String custTypeFilter = " cust_type IN(" + Utils.convertCommaSeparatedListToProperFormat2(Constants.userDetailsObj.getsecondary_cust_type(), "#") + ")";
        if (orderAuditType.equalsIgnoreCase("primary")) {
            custTypeFilter = " cust_type IN(" + Utils.convertCommaSeparatedListToProperFormat2(Constants.userDetailsObj.getprimary_cust_type(), "#") + ")";
        }
        String customQuery = "SELECT DISTINCT * FROM customer_master where " + custTypeFilter + " AND customer_code IN(SELECT DISTINCT customer_master.customer_code " + "FROM customer_master,outstanding_master " + "WHERE customer_master.acedns = 'Y' and customer_master.black_list = 'N' " + "and customer_master.route_code='" + routeCode + "' " + "and customer_master.customer_code = outstanding_master.customer_code  union select DISTINCT customer_code from order_header WHERE transaction_type='SB')";
        if (Constants.menuDetailsObj.getbargain().equalsIgnoreCase("yes") && MenuAccess("bargain") && Constants.menuDetailsObj.getDO().equalsIgnoreCase("yes") && MenuAccess("do")) {
            customQuery = "SELECT DISTINCT * FROM customer_master where  cust_type <> 'R' AND customer_code IN(SELECT DISTINCT customer_master.customer_code FROM customer_master,outstanding_master WHERE customer_master.acedns = 'Y' and customer_master.black_list = 'N' and customer_master.route_code='" + routeCode + "' and customer_master.customer_code=outstanding_master.customer_code )";
        }
        try (Cursor cursor = database.rawQuery(customQuery, null)) {
            if (cursor.getCount() > 0) {
                cursor.moveToFirst();
                for (int ii = 0; ii < cursor.getCount(); ii++) {
                    CustomerDetails detailsObj = new CustomerDetails();
                    detailsObj.setCustomerCode(cursor.getString(0));
                    detailsObj.setCustomerName(cursor.getString(1));
                    detailsObj.setRouteCode(cursor.getString(2));
                    detailsObj.setEmpCode(cursor.getString(3));
                    detailsObj.setIsBlackList(cursor.getString(4));
                    detailsObj.setIsACEDNS(cursor.getString(5));
                    detailsObj.setCreditLimit(cursor.getString(6));
                    detailsObj.setCurrentBalance(cursor.getString(7));
                    detailsObj.setTradeDiscount(cursor.getString(8));
                    detailsObj.setCustomerType(cursor.getString(9));
                    detailsObj.setRdsTag(cursor.getString(13));
                    detailsObj.setFlag(cursor.getString(14));
                    detailsObj.setSaudaValidityPeriod(cursor.getString(15));
                    detailList.add(detailsObj);
                    cursor.moveToNext();
                }
                return detailList;
            }
        } catch (Exception ignored) {
        }
        return detailList;
    }

