    public ArrayList<GITDetails> getGITDetailsList(String code) {
        ArrayList<GITDetails> grnList = new ArrayList<>();
        String sqlQuery;
        if (Constants.orderFormDetailsObj.getBranchRDSTransfer().equalsIgnoreCase("yes")) {
            sqlQuery = "SELECT DISTINCT Gt.grn_no,RD.rds_name FROM goods_in_transit GT,rds_master RD WHERE GT.status = '0' AND SUBSTR(GT.grn_no,2,5) = RD.emp_code AND GT.despatcher_code = '" + code + "' AND (GT.despatch_qty - (SELECT SUM(GT.bal_rec_qty) FROM goods_in_transit GT GROUP BY GT.prod_code,GT.grn_no) > 0)";
        } else {
            sqlQuery = "SELECT DISTINCT Gt.grn_no,BM.branch_name FROM goods_in_transit GT,branch_master BM WHERE GT.status = '0' AND SUBSTR(GT.grn_no,2,5) = BM.branch_code AND GT.despatcher_code = '" + code + "' AND (GT.despatch_qty - (SELECT SUM(GT.bal_rec_qty) FROM goods_in_transit GT GROUP BY GT.prod_code,GT.grn_no) > 0)";
        }
        try (Cursor cursor = database.rawQuery(sqlQuery, new String[]{})) {
            if (cursor.getCount() > 0) {
                cursor.moveToFirst();
                for (int ii = 0; ii < cursor.getCount(); ii++) {
                    GITDetails detailsObj = new GITDetails();
                    detailsObj.setGrnNo(cursor.getString(0));
                    detailsObj.setDespatcherName(cursor.getString(1));
                    grnList.add(detailsObj);
                    cursor.moveToNext();
                }
            }
        } catch (Exception ignored) {
        }
        return grnList;
    }

