    @SuppressLint("Recycle")
    public boolean checkIfStockAvailableForDistribution() {
        boolean status = false;
        int filterLevel = Integer.parseInt(Constants.productDetailsObj.getNoFilter());
        String selectQuery;
        if (filterLevel == 1) {
            if ((Constants.orderFormDetailsObj.getMrp().equalsIgnoreCase("yes") && Constants.orderFormDetailsObj.getMrpDrpdwn().equalsIgnoreCase("dropdown")) || ((Constants.orderFormDetailsObj.getSaleRate().equalsIgnoreCase("yes") && Constants.orderFormDetailsObj.getSaleRateDrpdwn().equalsIgnoreCase("dropdown")))) {
                selectQuery = "SELECT  DISTINCT PM.* FROM product_master PM,closing_stock CS,mrp MP WHERE PM.prod_code = CS.prod_code  AND PM.prod_code = MP.sku_code AND PM.acedns = 'Y' AND PM.black_list = 'N' AND CS.cl_stk  > '0.00'";
            } else {
                selectQuery = "SELECT  DISTINCT PM.* FROM product_master PM,closing_stock CS WHERE PM.prod_code = CS.prod_code AND PM.acedns = 'Y' AND PM.black_list = 'N' AND CS.cl_stk  > '0.00'";
            }
        } else {
            if ((Constants.orderFormDetailsObj.getMrp().equalsIgnoreCase("yes") && Constants.orderFormDetailsObj.getMrpDrpdwn().equalsIgnoreCase("dropdown")) || ((Constants.orderFormDetailsObj.getSaleRate().equalsIgnoreCase("yes") && Constants.orderFormDetailsObj.getSaleRateDrpdwn().equalsIgnoreCase("dropdown")))) {
                selectQuery = "SELECT  DISTINCT PGM.* FROM product_group_master PGM,product_master PM,closing_stock CS,mrp MP WHERE PGM.product_group_code = PM.product_group_code AND PM.prod_code = CS.prod_code  AND PM.prod_code = MP.sku_code AND PM.acedns = 'Y' AND PM.black_list = 'N' AND CS.cl_stk  > '0.00'";
            } else {
                selectQuery = "SELECT  DISTINCT PGM.* FROM product_group_master PGM,product_master PM,closing_stock CS WHERE PGM.product_group_code = PM.product_group_code AND PM.prod_code = CS.prod_code AND PM.acedns = 'Y' AND PM.black_list = 'N' AND CS.cl_stk  > '0.00'";
            }
        }
        Cursor cursor = database.rawQuery(selectQuery, null);
        if (cursor.getCount() > 0) {
            status = true;
        }
        return status;
    }

