    @SuppressLint("Recycle")
    public ArrayList<SelectedProductList> GetSelectedProductList(String branchcode, String verticalVal) {
        ArrayList<SelectedProductList> mSelectedProductList = new ArrayList<>();
        try (Cursor cursor1 = database.rawQuery("SELECT PGM.product_group_code,PGM.product_group_name,PM.prod_code,PM.prod_desc,PM.UOM1,PM.UOM2,PM.UOM3,PM.conversion_factor,PM.conversion_factor_two,PM.TD,MRP.mrp_code,MRP.sale_rate, MRP.basic_rate, MRP.primary_freight, MRP.depot_cost, PM.dns_prod_code FROM product_group_master PGM,product_master PM,sauda_mrp MRP WHERE PGM.product_group_code = PM.product_group_code AND PM.prod_code=MRP.sku_code AND PM.branch_code=MRP.branch_code AND PM.acedns ='Y' AND PM.vertical_value ='" + verticalVal + "' AND PM.black_list ='N' AND PM.branch_code=? ORDER BY PGM.product_group_code ASC ", new String[]{branchcode})) {
            if (cursor1.getCount() > 0) {
                cursor1.moveToFirst();
                for (int i = 0; i < cursor1.getCount(); i++) {
                    SelectedProductList prodObj = new SelectedProductList();
                    String currentProductGroupCode = cursor1.getString(0);
                    prodObj.setGroupCode(currentProductGroupCode);
                    prodObj.setGroupName(cursor1.getString(1));
                    prodObj.setProductCode(cursor1.getString(2));
                    prodObj.setProductDescription(cursor1.getString(3));
                    prodObj.setUOM1(cursor1.getString(4));
                    prodObj.setUOM2(cursor1.getString(5));
                    prodObj.setUOM3(cursor1.getString(6));
                    prodObj.setConversionFactor(cursor1.getString(7));
                    prodObj.setConversionFactorTwo(cursor1.getString(8));
                    prodObj.setTD(cursor1.getString(9));
                    prodObj.setMrpCode(cursor1.getString(10));
                    prodObj.setSaleRate(cursor1.getString(11));
                    prodObj.setBranchCode(branchcode);
                    prodObj.setBasicRate(cursor1.getString(12));
                    prodObj.setPrimaryFreight(cursor1.getString(13));
                    prodObj.setDepotCost(cursor1.getString(14));
                    prodObj.setDnsProductCode(cursor1.getString(15));
                    if (Constants.menuDetailsObj.getTD_allocation_vertical() != null && Constants.menuDetailsObj.getTD_allocation_vertical().contains((selectedVerticalOfUser))) {
                        String sqlQuery2 = "SELECT TD from TD_allocation where product_filter_code='" + currentProductGroupCode + "' AND emp_code='" + Constants.employeeDetailObject.getEmpCode() + "'";
                        Cursor cursor2 = database.rawQuery(sqlQuery2, null);
                        if (cursor2.getCount() > 0) {
                            cursor2.moveToFirst();
                            prodObj.setTD(cursor2.getString(0));
                        } else {
                            prodObj.setTD("0");
                        }
                    }
                    mSelectedProductList.add(prodObj);
                    cursor1.moveToNext();
                }
            }
        } catch (Exception ignored) {
        }
        return mSelectedProductList;
    }

