    private Boolean isSchemePresentForCurrentProdCode(String prodCode) {
        schemesListCurrentProdCode = new ArrayList<>();
        boolean isSchemePresent = false;
        String todaysDate = Utils.changeDateFormat("yyyyMMdd", "yyyy-MM-dd", dateString);
        try (Cursor cursor = database.rawQuery("SELECT * FROM scheme_master INNER JOIN freebies_master ON scheme_master.scheme_id=freebies_master.scheme_id AND trim(scheme_master.scheme_type)!='cumulative' AND scheme_master.prod_code='" + prodCode + "' AND '" + todaysDate + "' >= scheme_master.start_date AND '" + todaysDate + "' <= scheme_master.end_date", null)) {
            if (cursor.getCount() > 0) {
                isSchemePresent = true;
                cursor.moveToFirst();
                for (int i = 0; i < cursor.getCount(); i++) {
                    SchemeFreebiesDetails detailsItem = new SchemeFreebiesDetails();
                    String schemeId = cursor.getString(0);
                    detailsItem.setschemeId(schemeId);
                    detailsItem.setstartDate(cursor.getString(1));
                    detailsItem.setendDate(cursor.getString(2));
                    detailsItem.setprodCode(cursor.getString(3));
                    detailsItem.setqty(cursor.getString(4));
                    detailsItem.setamount(cursor.getString(5));
                    detailsItem.setscheme_type(cursor.getString(6));
                    detailsItem.setscheme_filter(cursor.getString(7));
                    detailsItem.setProductUom(cursor.getString(8));
                    detailsItem.setfreebiesProdCode(cursor.getString(10));
                    detailsItem.setfreebiesProdDesc(cursor.getString(11));
                    detailsItem.setFreebieQty(cursor.getString(12));
                    detailsItem.setvaluePercent(cursor.getString(13));
                    detailsItem.setvalueAmount(cursor.getString(14));
                    detailsItem.setFreebieUom(cursor.getString(15));
                    detailsItem.setProductUomDisplayValue(setProductUomDisplayValueFromUomType(cursor.getString(8).toLowerCase(), cursor.getString(3), "dns_prod_code"));
                    detailsItem.setfreebieUomDisplayValue(setProductUomDisplayValueFromUomType(cursor.getString(15).toLowerCase(), cursor.getString(3), "dns_prod_code"));
                    if (schemeListForCurrentProducts.containsKey(schemeId)) {
                        ArrayList<SchemeFreebiesDetails> tempArrayList = schemeListForCurrentProducts.get(schemeId);
                        tempArrayList.add(detailsItem);
                        schemeListForCurrentProducts.put(schemeId, tempArrayList);
                    } else {
                        ArrayList<SchemeFreebiesDetails> tempArrayList = new ArrayList<>();
                        tempArrayList.add(detailsItem);
                        schemeListForCurrentProducts.put(schemeId, tempArrayList);
                    }
                    if (!schemesListCurrentProdCode.contains(schemeId)) {
                        schemesListCurrentProdCode.add(schemeId);
                    }
                    cursor.moveToNext();
                }
            }
        } catch (Exception e) {
            isSchemePresent = false;
        }
        return isSchemePresent;
    }

    public double conversionfactorForCurrentProduct(String columnName, String prodCode, String filter) {
        String query;
        if (filter.equalsIgnoreCase("1")) {
            query = "select " + columnName + " from product_master where dns_prod_code='" + prodCode + "'";
        } else {
            query = "select " + columnName + " from product_master where product_group_code='" + prodCode + "'";
        }
        try (Cursor cursor = database.rawQuery(query, null)) {
            if (cursor.getCount() > 0) {
                cursor.moveToFirst();
                return Double.parseDouble(cursor.getString(0));
            }
        } catch (Exception ignored) {
        }
        return 0;
    }

