    public ArrayList<MRPDetails> getMRPListForOrder(String productCode, String selectedUOM, String conversionFactor) {
        ArrayList<MRPDetails> mrpList = new ArrayList<>();
        Cursor cursor = null;
        try {
            if (Constants.productDetailsObj.getDestinationOrderTypePriceList().equalsIgnoreCase("yes")) {
                if (selectedUOM.isEmpty()) {
                    cursor = database.rawQuery("SELECT * FROM mrp where sku_code='" + productCode + "' AND destination_code='" + Constants.mDestinationCode + "' AND order_type='" + Constants.mOrderType + "' AND acedns='Y'", null);
                } else {
                    cursor = database.rawQuery("SELECT * FROM mrp where sku_code='" + productCode + "' AND UOM = '" + selectedUOM + "' AND destination_code='" + Constants.mDestinationCode + "' AND order_type='" + Constants.mOrderType + "' AND acedns='Y'", null);
                }
            } else {
                if (selectedUOM.isEmpty()) {
                    cursor = database.rawQuery("SELECT * FROM mrp where sku_code='" + productCode + "' AND acedns='Y'", null);
                } else {
                    cursor = database.rawQuery("SELECT * FROM mrp where sku_code='" + productCode + "' AND UOM = '" + selectedUOM + "' AND acedns='Y'", null);
                }
            }
            cursor.moveToFirst();
            if (cursor.getCount() > 0) {
                for (int ii = 0; ii < cursor.getCount(); ii++) {
                    MRPDetails detailsObj = new MRPDetails();
                    detailsObj.setProdCode(cursor.getString(0));
                    detailsObj.setMrpCode(cursor.getString(1));
                    String mrpVal = String.valueOf(Double.parseDouble(cursor.getString(2)) / Double.parseDouble(conversionFactor));
                    String SaleRate = String.valueOf(Double.parseDouble(cursor.getString(3)) / Double.parseDouble(conversionFactor));
                    detailsObj.setMrpValue(mrpVal);
                    detailsObj.setSaleRate(SaleRate);
                    detailsObj.setUom(cursor.getString(4));
                    detailsObj.setBranchCode(cursor.getString(5));
                    detailsObj.setWSRate(cursor.getString(9));
                    detailsObj.setDistributorRate(cursor.getString(10));
                    detailsObj.setSSRate(cursor.getString(11));
                    detailsObj.setDepotRate(cursor.getString(12));
                    mrpList.add(detailsObj);
                    cursor.moveToNext();
                }
                cursor.close();
            }
            cursor.close();
        } catch (Exception ignored) {
        } finally {
            if (cursor != null) {
                cursor.close();
            }
        }
        return mrpList;
    }

