    public ArrayList<MenuAegingListChild> getAgeingDetailsForMenu(ArrayList<MenuOutstandingParent> parentList, int period1, int period2) {
        ArrayList<MenuAegingListChild> childList = new ArrayList<>();
        Cursor cursor = null;
        try {
            for (int kk = 0; kk < parentList.size(); kk++) {
                String query = "SELECT recid,invoice_id,due_amount,(SELECT julianday('now') - julianday(date) AS 'Due Days') FROM outstanding_master WHERE customer_code = '" + parentList.get(kk).getCustomerCode() + "' ORDER BY recid";
                cursor = null;
                cursor = database.rawQuery(query, null);
                if (cursor.getCount() > 0) {
                    MenuAegingListChild childObj = new MenuAegingListChild();
                    ArrayList<AgeingDetails> detailList = new ArrayList<>();
                    cursor.moveToFirst();
                    for (int ii = 0; ii < cursor.getCount(); ii++) {
                        AgeingDetails detailsObj = new AgeingDetails();
                        detailsObj.setParty(cursor.getString(0));
                        detailsObj.setInvNo(cursor.getString(1));
                        int dueDays = (int) (Double.parseDouble(cursor.getString(3)));
                        if (dueDays <= period1) {
                            detailsObj.setPeriod1(cursor.getString(2));
                        } else if (dueDays <= period2) {
                            detailsObj.setPeriod2(cursor.getString(2));
                        } else {
                            detailsObj.setPeriod3(cursor.getString(2));
                        }
                        detailList.add(detailsObj);
                        cursor.moveToNext();
                    }
                    childObj.setAgeingChildList(detailList);
                    childList.add(childObj);
                    cursor.close();
                } else {
                    cursor.close();
                }
            }
        } catch (Exception ignored) {
        } finally {
            if (cursor != null) {
                cursor.close();
            }
        }
        return childList;
    }

    public ArrayList<MenuClStkMrpDetails> getMenuMrpList(String branchcode, String type) {
        ArrayList<MenuClStkMrpDetails> mrpList = new ArrayList<>();
        String selectQuery;
        if (Constants.saudaFormDetailsObj.getSaudaDepotWise().equalsIgnoreCase("yes")) {
            if (type.equalsIgnoreCase("sauda")) {
                selectQuery = "SELECT PM.prod_desc,MRP.mrp_value  FROM  sauda_mrp MRP,product_master PM WHERE  MRP.sku_code=PM.prod_code AND PM.acedns = 'Y' AND PM.black_list = 'N'  AND MRP.branch_code='" + branchcode + "'  ORDER BY PM.prod_desc ASC";
            } else {
                selectQuery = "SELECT PM.prod_desc,MRP.sale_rate  FROM  mrp MRP,product_master PM WHERE  MRP.sku_code=PM.prod_code AND PM.acedns = 'Y' AND PM.black_list = 'N'  AND MRP.branch_code='" + branchcode + "'  ORDER BY PM.prod_desc ASC";
            }
        } else {
            if (Constants.orderFormDetailsObj.getMrp().equalsIgnoreCase("yes")) {
                selectQuery = "SELECT PM.prod_desc,MRP.mrp_value FROM product_master PM,mrp MRP WHERE PM.prod_code = MRP.sku_code AND PM.acedns = 'Y' AND PM.black_list = 'N'";
            } else {
                selectQuery = "SELECT PM.prod_desc,MRP.sale_rate FROM product_master PM,mrp MRP WHERE PM.prod_code = MRP.sku_code AND PM.acedns = 'Y' AND PM.black_list = 'N'";
            }
        }
        try (Cursor cursor = database.rawQuery(selectQuery, null)) {
            if (cursor.getCount() > 0) {
                cursor.moveToFirst();
                for (int ii = 0; ii < cursor.getCount(); ii++) {
                    MenuClStkMrpDetails detailsObj = new MenuClStkMrpDetails();
                    detailsObj.setProduct(cursor.getString(0));
                    detailsObj.setValue(cursor.getString(1));
                    mrpList.add(detailsObj);
                    cursor.moveToNext();
                }
            }
        } catch (Exception ignored) {
        }
        return mrpList;
    }

    public ArrayList<MenuClStkMrpDetails> getMenuMrpListForIncoTerms(String branchcode) {
        ArrayList<MenuClStkMrpDetails> mrpList = new ArrayList<>();
        String selectQuery;
        if (Constants.selectedBranch.getisPlant().equalsIgnoreCase("yes")) {
            selectQuery = "SELECT PM.prod_desc,MRP.basic_rate,0, 0,PM.prod_code, PM.dns_prod_code FROM  sauda_mrp MRP,product_master PM WHERE  MRP.sku_code=PM.prod_code AND PM.acedns = 'Y' AND PM.black_list = 'N'  AND MRP.branch_code='" + branchcode + "' AND MRP.basic_rate>0 ORDER BY PM.prod_desc ASC";
        } else {
            selectQuery = "SELECT PM.prod_desc,MRP.basic_rate, mrp.primary_freight, mrp.depot_cost,PM.prod_code, PM.dns_prod_code  FROM  sauda_mrp MRP,product_master PM WHERE  MRP.sku_code=PM.prod_code AND PM.acedns = 'Y' AND PM.black_list = 'N'  AND MRP.branch_code='" + branchcode + "' AND MRP.basic_rate>0  ORDER BY PM.prod_desc ASC";
        }
        try (Cursor cursor = database.rawQuery(selectQuery, null)) {
            if (cursor.getCount() > 0) {
                cursor.moveToFirst();
                for (int ii = 0; ii < cursor.getCount(); ii++) {
                    boolean isPrimaryFreightOk, isDepotCostOk;
                    MenuClStkMrpDetails detailsObj = new MenuClStkMrpDetails();
                    detailsObj.setProduct(cursor.getString(0));
                    detailsObj.setValue(cursor.getString(1));
                    String currentPrimaryFreight = cursor.getString(2);
                    detailsObj.setPrimaryFreight(currentPrimaryFreight);
                    String currentDepotCost = cursor.getString(3);
                    detailsObj.setDepotCost(currentDepotCost);
                    String prodCode = cursor.getString(4);
                    detailsObj.setprodCode(prodCode);
                    String dnsProdCode = cursor.getString(5);
                    detailsObj.setHoneycombCost(getHoneyCombCostByProdCodeStateCode(dnsProdCode));
                    detailsObj.setMarginCost(getMarginCostByProdCodeStateCode(dnsProdCode));
                    isPrimaryFreightOk = Constants.selectedBranch.getisPlant().equalsIgnoreCase("yes") || (Utils.isNumeric(currentPrimaryFreight) && !(Double.parseDouble(currentPrimaryFreight) <= 0));
                    isDepotCostOk = Constants.selectedBranch.getisPlant().equalsIgnoreCase("yes") || Utils.isNumeric(currentDepotCost);
                    if (isPrimaryFreightOk && isDepotCostOk) {
                        mrpList.add(detailsObj);
                    }
                    cursor.moveToNext();
                }
            }
        } catch (Exception ignored) {
        }
        return mrpList;
    }

