    public void insertToLogTable(String timeStamp, String tableName) {
        database.beginTransaction();
        try {
            database.execSQL("DELETE FROM data_download_log WHERE table_name = '" + tableName + "'");
            database.setTransactionSuccessful();
        } catch (Exception ignored) {
        } finally {
            database.endTransaction();
        }
        database.beginTransaction();
        try {
            ContentValues cv = new ContentValues();
            cv.put("table_name", tableName);
            cv.put("last_download_time", timeStamp);
            cv.put("is_download ", (Constants.isDataRefreshed ? "no" : "yes"));
            cv.put("is_refresh ", (Constants.isDataRefreshed ? "yes" : "no"));
            synchronized (Lock) {
                database.insertWithOnConflict("data_download_log", null, cv, SQLiteDatabase.CONFLICT_IGNORE);
                database.setTransactionSuccessful();
            }
        } catch (Exception ignored) {
        } finally {
            database.endTransaction();
        }
    }

