    public String getCheckInValueByColumnName(String columnName) {
        String returnValue = "";
        columnName = columnName.trim();
        try {
            database.beginTransaction();
            Cursor cursor = database.rawQuery("SELECT variable_value FROM app_variables where operation_type='checkin' AND variable_name='" + columnName + "'", null);
            if (cursor.getCount() > 0) {
                cursor.moveToFirst();
                returnValue = cursor.getString(0);
                cursor.close();
            }
            database.setTransactionSuccessful();
        } catch (Exception ignored) {
        } finally {
            database.endTransaction();
        }
        return returnValue;
    }

    public void setCheckInValueByColumnName(String variable_name, String variable_value) {
        database.beginTransaction();
        try {
            ContentValues cv = new ContentValues();
            cv.put("nick_name", Constants.userDetailsObj.getNickName());
            cv.put("variable_name", variable_name);
            cv.put("variable_value", variable_value);
            cv.put("operation_type", "checkin");
            synchronized (Lock) {
                database.insertWithOnConflict("app_variables", null, cv, SQLiteDatabase.CONFLICT_IGNORE);
                database.setTransactionSuccessful();
            }
        } catch (Exception ignored) {
        } finally {
            database.endTransaction();
        }
    }

