    public long insertToYellowCardValidationCustomerwise(ArrayList<YellowCardDateValidation> catalogueList) {
        long status = 0;
        int ii;
        database.beginTransaction();
        try {
            for (ii = 0; ii < catalogueList.size(); ii++) {
                YellowCardDateValidation detailObj = catalogueList.get(ii);
                ContentValues cv = new ContentValues();
                cv.put("customer_code", detailObj.getCustomer_code());
                cv.put("validation_from", detailObj.getValidation_from());
                cv.put("validation_to", detailObj.getValidation_to());
                cv.put("validation_last_date", detailObj.getValidation_last_date());
                if (Constants.isFirstLoginOfApp || Constants.isSiteTableUpdated) {
                    synchronized (Lock) {
                        database.insertWithOnConflict("yellow_card_date_validation_customerwise", null, cv, SQLiteDatabase.CONFLICT_IGNORE);
                    }
                } else {
                    database.execSQL("DELETE FROM yellow_card_date_validation_customerwise  WHERE customer_code='" + detailObj.getCustomer_code() + "'");
                    database.insertWithOnConflict("yellow_card_date_validation_customerwise", null, cv, SQLiteDatabase.CONFLICT_IGNORE);
                }
            }
            status = ii;
            database.setTransactionSuccessful();
        } catch (SQLException ignored) {
        } finally {
            database.endTransaction();
        }
        return status;
    }

